local CuttingBoardMaker = {}
local PRODUCTS = {
    iron_cutting_board = { name = "Železna deska za rezanje", ironCost = 1, woodCost = 4, leatherCost = 1, time = 4, cost = 140, prestige = 3, happiness = 2, description = "Železna deska za rezanje v kuhinji." },
    bronze_cutting_board = { name = "Bronasta deska za rezanje", bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 1, time = 6, cost = 340, prestige = 5, happiness = 3, description = "Bronasta deska za rezanje v pekarni." },
    silver_cutting_board = { name = "Srebrna deska za rezanje", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 1, time = 10, cost = 820, prestige = 10, happiness = 4, description = "Srebrna deska za plemiške kuharje." },
    gilded_cutting_board = { name = "Pozlačena deska za rezanje", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 14, cost = 1780, prestige = 19, happiness = 5, description = "Pozlačena deska za dvorne kuharje." },
    jewel_set_cutting_board = { name = "Draguljasta deska za rezanje", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 18, cost = 3850, prestige = 35, happiness = 7, description = "Draguljasta deska za kraljeve kuharje." },
    royal_sovereign_cutting_board = { name = "Kraljevski suverena deska za rezanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 5, leatherCost = 1, time = 25, cost = 8300, prestige = 67, happiness = 13, description = "Suverena deska z biseri za krono." },
}
local BUILDINGS = {
    cuttingboard_workshop = { name = "Rezalna delavnica", cost = { gold = 305, wood = 195, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    cuttingboard_house = { name = "Rezalna hiša", cost = { gold = 1130, wood = 380, stone = 255, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_cuttingboard_atelier = { name = "Mojstrski rezalni atelje", cost = { gold = 2900, wood = 440, stone = 495, silver = 33, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    sovereign_cuttingboard_palace = { name = "Suverena rezalna palača", cost = { gold = 12550, wood = 670, stone = 805, gold = 80, jewel = 18 }, upkeep = 247, qualityBonus = 55, prestigeBonus = 50 },
}
CuttingBoardMaker.ironStock = 10; CuttingBoardMaker.bronzeStock = 8; CuttingBoardMaker.woodStock = 20; CuttingBoardMaker.leatherStock = 8; CuttingBoardMaker.silverStock = 8; CuttingBoardMaker.goldStock = 6; CuttingBoardMaker.jewelStock = 4; CuttingBoardMaker.pearlStock = 4
CuttingBoardMaker.productStock = {}; CuttingBoardMaker.buildings = {}; CuttingBoardMaker.maker = nil; CuttingBoardMaker.activeMaking = {}; CuttingBoardMaker.totalProducts = 0; CuttingBoardMaker.dayTimer = 0
function CuttingBoardMaker.init() CuttingBoardMaker.ironStock=10; CuttingBoardMaker.bronzeStock=8; CuttingBoardMaker.woodStock=20; CuttingBoardMaker.leatherStock=8; CuttingBoardMaker.silverStock=8; CuttingBoardMaker.goldStock=6; CuttingBoardMaker.jewelStock=4; CuttingBoardMaker.pearlStock=4; CuttingBoardMaker.productStock={}; CuttingBoardMaker.buildings={}; CuttingBoardMaker.maker=nil; CuttingBoardMaker.activeMaking={}; CuttingBoardMaker.totalProducts=0; CuttingBoardMaker.dayTimer=0; print("[CuttingBoardMaker] Royal Cutting Board Maker System initialized (6 products, 4 buildings)") end
function CuttingBoardMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CuttingBoardMaker.maker={name=n or ("Rezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezar najet: %s (spretnost: %d)",CuttingBoardMaker.maker.name,s),"success") end; return true end
function CuttingBoardMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CuttingBoardMaker.build(id) local ok,e=CuttingBoardMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CuttingBoardMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CuttingBoardMaker.getQualityBonus() local b=0; for _,bd in ipairs(CuttingBoardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CuttingBoardMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CuttingBoardMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CuttingBoardMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CuttingBoardMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CuttingBoardMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CuttingBoardMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CuttingBoardMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CuttingBoardMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CuttingBoardMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CuttingBoardMaker.buildings==0 then return false,"Potrebna rezalna delavnica" end; if not CuttingBoardMaker.maker then return false,"Potreben rezar" end; return true end
function CuttingBoardMaker.make(pt,qty) qty=qty or 1; local ok,e=CuttingBoardMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CuttingBoardMaker.ironStock=CuttingBoardMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CuttingBoardMaker.bronzeStock=CuttingBoardMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CuttingBoardMaker.woodStock=CuttingBoardMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CuttingBoardMaker.leatherStock=CuttingBoardMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CuttingBoardMaker.silverStock=CuttingBoardMaker.silverStock-d.silverCost*qty end; if d.goldCost then CuttingBoardMaker.goldStock=CuttingBoardMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CuttingBoardMaker.jewelStock=CuttingBoardMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CuttingBoardMaker.pearlStock=CuttingBoardMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CuttingBoardMaker.maker then t=math.max(1,t-math.floor(CuttingBoardMaker.maker.skill/13)) end; table.insert(CuttingBoardMaker.activeMaking,{id="cuttingboard_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CuttingBoardMaker.completeMaking(m) local q=1.0+(CuttingBoardMaker.getQualityBonus()/100); if CuttingBoardMaker.maker then q=q+(CuttingBoardMaker.maker.skill/140) end; q=math.min(2.5,q); CuttingBoardMaker.productStock[m.productType]=(CuttingBoardMaker.productStock[m.productType] or 0)+m.quantity; CuttingBoardMaker.totalProducts=CuttingBoardMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CuttingBoardMaker.maker then CuttingBoardMaker.maker.itemsMade=CuttingBoardMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CuttingBoardMaker.maker.skill=math.min(100,CuttingBoardMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Deska izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cuttingboard.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function CuttingBoardMaker.update(dt) if not _G.state then return end; CuttingBoardMaker.dayTimer=CuttingBoardMaker.dayTimer+dt; if CuttingBoardMaker.dayTimer>=30 then CuttingBoardMaker.dayTimer=0; for i=#CuttingBoardMaker.activeMaking,1,-1 do local m=CuttingBoardMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CuttingBoardMaker.completeMaking(m); table.remove(CuttingBoardMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CuttingBoardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CuttingBoardMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CuttingBoardMaker.getStats() return {ironStock=CuttingBoardMaker.ironStock,bronzeStock=CuttingBoardMaker.bronzeStock,woodStock=CuttingBoardMaker.woodStock,leatherStock=CuttingBoardMaker.leatherStock,silverStock=CuttingBoardMaker.silverStock,goldStock=CuttingBoardMaker.goldStock,jewelStock=CuttingBoardMaker.jewelStock,pearlStock=CuttingBoardMaker.pearlStock,productStock=CuttingBoardMaker.productStock,numBuildings=#CuttingBoardMaker.buildings,hasMaker=CuttingBoardMaker.maker~=nil,makerName=CuttingBoardMaker.maker and CuttingBoardMaker.maker.name or "—",makerSkill=CuttingBoardMaker.maker and CuttingBoardMaker.maker.skill or 0,activeMaking=#CuttingBoardMaker.activeMaking,totalProducts=CuttingBoardMaker.totalProducts} end
return CuttingBoardMaker
